import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TouchableOpacity,
  TextInput,
  ImageBackground,
  Alert,
  Modal,
  Platform,
  KeyboardAvoidingView,
} from 'react-native';
import { getFirestore, collection, getDocs, addDoc, deleteDoc, doc, Timestamp, orderBy, query } from 'firebase/firestore';
import { MaterialIcons, MaterialCommunityIcons } from '@expo/vector-icons';
import { getAuth } from 'firebase/auth';
import { useNavigation } from '@react-navigation/native';

const db = getFirestore();

const IUDS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
];

type Agendamento = {
  id?: string;
  titulo: string;
  data: string;
  descricao?: string;
  criadoEm?: any;
};

// Função para formatar data com barra automaticamente (sempre com '/')
function formatarDataInput(text: string) {
  let cleaned = text.replace(/\D/g, '');
  let formatted = '';
  if (cleaned.length > 4) {
    formatted = cleaned.replace(/^(\d{2})(\d{2})(\d{0,4}).*/, '$1/$2/$3');
  } else if (cleaned.length > 2) {
    formatted = cleaned.replace(/^(\d{2})(\d{0,2})/, '$1/$2');
  } else {
    formatted = cleaned;
  }
  return formatted;
}

export default function TelaAgenda() {
  const [agendamentos, setAgendamentos] = useState<Agendamento[]>([]);
  const [novoTitulo, setNovoTitulo] = useState('');
  const [novaData, setNovaData] = useState('');
  const [novaDescricao, setNovaDescricao] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [uidAtual, setUidAtual] = useState<string | null>(null);

  const navigation = useNavigation();

  useEffect(() => {
    setUidAtual(getAuth().currentUser?.uid ?? null);
    buscarAgendamentos();
  }, []);

  async function buscarAgendamentos() {
    try {
      const q = query(collection(db, 'agendas'), orderBy('data'));
      const snap = await getDocs(q);
      const lista: Agendamento[] = [];
      snap.forEach(doc => {
        lista.push({ id: doc.id, ...doc.data() } as Agendamento);
      });
      setAgendamentos(lista);
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível carregar os agendamentos.');
    }
  }

  async function adicionarAgendamento() {
    // Salva sempre no formato dd/mm/aaaa
    const dataFormatada = novaData;
    if (!novoTitulo || !dataFormatada.match(/^\d{2}\/\d{2}\/\d{4}$/)) {
      Alert.alert('Preencha corretamente o título e a data (dd/mm/aaaa)');
      return;
    }
    try {
      await addDoc(collection(db, 'agendas'), {
        titulo: novoTitulo,
        data: dataFormatada,
        descricao: novaDescricao,
        criadoEm: Timestamp.now(),
      });
      setNovoTitulo('');
      setNovaData('');
      setNovaDescricao('');
      setModalVisible(false);
      buscarAgendamentos();
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível adicionar.');
    }
  }

  // Novo método de exclusão (igual repertorios)
  const excluirAgendamento = async (id: string | undefined) => {
    if (!id || !uidAtual || !IUDS.includes(uidAtual)) return;
    try {
      await getAuth().currentUser?.getIdToken(true);
      await deleteDoc(doc(db, 'agendas', id));
      setAgendamentos(prev => prev.filter(ag => ag.id !== id));
    } catch (error: any) {
      console.log('Erro ao excluir agendamento:', error);
    }
  };

  return (
    <ImageBackground
      source={require('../assets/fun.jpg')}
      style={estilos.bg}
      resizeMode="cover"
      blurRadius={2}
    >
      <View style={estilos.overlay} />
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <View style={estilos.container}>
          {/* Botão Home à esquerda e Voltar à direita */}
          <View style={estilos.headerBotoes}>
            <TouchableOpacity
              style={estilos.headerBotao}
              onPress={() => navigation.navigate('Inicio' as never)}
            >
              <MaterialIcons name="home" size={28} color="#2196F3" />
            </TouchableOpacity>
            <View style={{ flex: 1 }} />
            <TouchableOpacity
              style={estilos.headerBotao}
              onPress={() => navigation.goBack()}
            >
              <MaterialIcons name="arrow-forward" size={28} color="#2196F3" />
            </TouchableOpacity>
          </View>

          <Text style={estilos.titulo}>📅 Agenda de Compromissos</Text>

          {uidAtual && IUDS.includes(uidAtual) && (
            <TouchableOpacity style={estilos.botaoAbrirModal} onPress={() => setModalVisible(true)}>
              <MaterialIcons name="add-circle" size={28} color="#fff" />
              <Text style={estilos.textoBotaoAdd}>Novo Agendamento</Text>
            </TouchableOpacity>
          )}

          <FlatList
            data={agendamentos}
            keyExtractor={item => item.id || item.titulo + item.data}
            contentContainerStyle={{ paddingBottom: 40, marginTop: 18 }}
            renderItem={({ item }) => (
              <View style={estilos.card}>
                <View style={estilos.cardHeader}>
                  <MaterialCommunityIcons name="calendar-star" size={26} color="#1976d2" style={{ marginRight: 10 }} />
                  <View style={{ flex: 1 }}>
                    <Text style={estilos.cardTitulo}>{item.titulo}</Text>
                    <Text style={estilos.cardData}>🗓 {item.data}</Text>
                  </View>
                  {uidAtual && IUDS.includes(uidAtual) && (
                    <TouchableOpacity
                      onPress={() => excluirAgendamento(item.id)}
                      style={estilos.botaoExcluir}
                    >
                      <MaterialIcons name="delete" size={22} color="#e53935" />
                    </TouchableOpacity>
                  )}
                </View>
                {item.descricao ? (
                  <View style={estilos.cardDescricaoBox}>
                    <MaterialIcons name="notes" size={18} color="#1976d2" style={{ marginRight: 4 }} />
                    <Text style={estilos.cardDescricao}>{item.descricao}</Text>
                  </View>
                ) : null}
              </View>
            )}
            ListEmptyComponent={
              <View style={{ alignItems: 'center', marginTop: 40 }}>
                <MaterialCommunityIcons name="calendar-remove" size={48} color="#2196F3" />
                <Text style={{ color: '#2196F3', textAlign: 'center', marginTop: 10, fontSize: 16 }}>
                  Nenhum agendamento cadastrado.
                </Text>
              </View>
            }
          />

          <Modal
            visible={modalVisible}
            animationType="fade"
            transparent
            onRequestClose={() => setModalVisible(false)}
          >
            <View style={estilos.modalBg}>
              <View style={estilos.modalBox}>
                <Text style={estilos.modalTitulo}>Novo Agendamento</Text>
                <View style={estilos.inputBox}>
                  <MaterialIcons name="title" size={20} color="#2196F3" style={{ marginRight: 6 }} />
                  <TextInput
                    style={estilos.input}
                    placeholder="Título"
                    value={novoTitulo}
                    onChangeText={setNovoTitulo}
                    placeholderTextColor="#2196F3"
                  />
                </View>
                <View style={estilos.inputBox}>
                  <MaterialIcons name="calendar-today" size={20} color="#2196F3" style={{ marginRight: 6 }} />
                  <TextInput
                    style={estilos.input}
                    placeholder="Data"
                    value={novaData}
                    onChangeText={text => setNovaData(formatarDataInput(text))}
                    placeholderTextColor="#2196F3"
                    keyboardType="numeric"
                    maxLength={10}
                  />
                </View>
                <View style={estilos.inputBox}>
                  <MaterialIcons name="description" size={20} color="#2196F3" style={{ marginRight: 6 }} />
                  <TextInput
                    style={[estilos.input, { minHeight: 40 }]}
                    placeholder="Descrição (opcional)"
                    value={novaDescricao}
                    onChangeText={setNovaDescricao}
                    placeholderTextColor="#2196F3"
                    multiline
                  />
                </View>
                <View style={{ flexDirection: 'row', justifyContent: 'flex-end', gap: 12, marginTop: 10 }}>
                  <TouchableOpacity onPress={() => setModalVisible(false)}>
                    <Text style={{ color: '#e53935', fontWeight: 'bold', fontSize: 16 }}>Cancelar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity onPress={adicionarAgendamento}>
                    <Text style={{ color: '#2196F3', fontWeight: 'bold', fontSize: 16 }}>Salvar</Text>
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          </Modal>
        </View>
      </KeyboardAvoidingView>
    </ImageBackground>
  );
}

