import React, { useEffect } from 'react';
import { View, ActivityIndicator, StyleSheet, Platform, Text, Alert, Linking } from 'react-native';
import { WebView } from 'react-native-webview';
import { useRoute, useNavigation, RouteProp } from '@react-navigation/native';

// Tipagem para os parâmetros da rota
type VisualizarArquivoParams = {
  url: string;
  nome?: string;
};

export default function VisualizarArquivo() {
  // Tipando corretamente o route.params
  const route = useRoute<RouteProp<{ params: VisualizarArquivoParams }, 'params'>>();
  const navigation = useNavigation();
  const { url, nome } = route.params;

  useEffect(() => {
    if (Platform.OS === 'web') {
      window.open(url, '_blank');
      setTimeout(() => {
        navigation.goBack();
      }, 500);
    }
  }, [url, navigation]);

  if (Platform.OS === 'web') {
    return (
      <View style={styles.webFallback}>
        <Text style={{ color: '#2196F3', fontSize: 16 }}>
          O arquivo foi aberto em uma nova aba do navegador.
        </Text>
      </View>
    );
  }

  // Pergunta ao usuário qual visualizador deseja usar
  useEffect(() => {
    Alert.alert(
      'Abrir arquivo',
      'Como você deseja visualizar o arquivo?',
      [
        {
          text: 'Visualizador interno',
          onPress: () => {}, // Não faz nada, apenas exibe o WebView abaixo
        },
        {
          text: 'Outro app',
          onPress: () => {
            Linking.openURL(url);
            navigation.goBack();
          },
        },
        { text: 'Cancelar', style: 'cancel', onPress: () => navigation.goBack() },
      ],
      { cancelable: false }
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Detecta extensão do arquivo
  const lowerUrl = url.toLowerCase();
  const isDoc = lowerUrl.endsWith('.pdf') || lowerUrl.endsWith('.docx');
  // Para PDF/DOCX, usa Google Docs Viewer, para imagens e outros, abre direto
  // Adiciona um parâmetro único para evitar cache em todos os tipos de arquivo
  const noCacheUrl = url.includes('?')
    ? `${url}&_t=${Date.now()}`
    : `${url}?_t=${Date.now()}`;
  const viewerUrl = isDoc
    ? `https://docs.google.com/gview?embedded=true&url=${encodeURIComponent(noCacheUrl)}&t=${Date.now()}`
    : noCacheUrl;

  return (
    <View style={{ flex: 1 }}>
      <WebView
        key={viewerUrl}
        source={{ uri: viewerUrl }}
        cacheEnabled={false}
        cacheMode="LOAD_NO_CACHE"
        startInLoadingState
        renderLoading={() => (
          <ActivityIndicator size="large" color="#2196F3" style={styles.loading} />
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  loading: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  webFallback: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#F5F7FA',
    padding: 24,
  },
});