import React, { useState } from 'react';
import {
  TextInput,
  Text,
  StyleSheet,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
  TouchableOpacity,
  View,
} from 'react-native';
import { auth } from '../services/firebaseConfig';
import {
  createUserWithEmailAndPassword,
  sendEmailVerification,
} from 'firebase/auth';
import { getFirestore, setDoc, doc } from 'firebase/firestore';
import Toast from 'react-native-toast-message';

const db = getFirestore();

export default function TelaCadastro({ navigation }: any): JSX.Element {
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');

  async function registrarUsuario() {
    if (!email || !senha) {
      Toast.show({
        type: 'error',
        text1: 'Erro',
        text2: 'Preencha email e senha',
      });
      return;
    }

    // Toast imediato ao clicar no botão
    Toast.show({
      type: 'info',
      text1: 'Atenção',
      text2: 'Verifique seu e-mail e confirme antes de fazer login.',
      visibilityTime: 3500,
    });

    try {
      const credencial = await createUserWithEmailAndPassword(auth, email, senha);
      const usuario = credencial.user;

      await sendEmailVerification(usuario);

      await setDoc(doc(db, 'usuarios', usuario.uid), {
        email: usuario.email,
        criadoEm: new Date(),
      });

      Toast.show({
        type: 'success',
        text1: 'Cadastro realizado!',
        text2: `Um e-mail de confirmação foi enviado para ${usuario.email}.`,
        visibilityTime: 3500,
        onHide: () => navigation.replace('Login'),
      });

    } catch (erro: any) {
      let mensagem = 'Cadastro usuário.';
      if (erro.code === 'auth/email-already-in-use') {
        mensagem = 'Este e-mail já está cadastrado.';
      } else if (erro.code === 'auth/invalid-email') {
        mensagem = 'E-mail inválido.';
      } else if (erro.code === 'auth/weak-password') {
        mensagem = 'Senha muito fraca. Use pelo menos 6 caracteres.';
      }

      Toast.show({
        type: 'error',
        text1: 'Erro',
        text2: mensagem,
      });
    }
  }

  return (
    <KeyboardAvoidingView
      style={{ flex: 1 }}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView
        contentContainerStyle={estilos.container}
        keyboardShouldPersistTaps="handled"
      >
        <TextInput
          placeholder="Email"
          value={email}
          onChangeText={setEmail}
          autoCapitalize="none"
          keyboardType="email-address"
          style={estilos.input}
        />
        <TextInput
          placeholder="Senha"
          value={senha}
          onChangeText={setSenha}
          secureTextEntry
          style={estilos.input}
        />
        <TouchableOpacity style={estilos.botao} onPress={registrarUsuario}>
          <Text style={estilos.textoBotao}>Cadastrar</Text>
        </TouchableOpacity>

        {/* Botão Voltar abaixo do botão Cadastrar */}
        <View style={{ flexDirection: 'row', justifyContent: 'flex-end', marginTop: 18 }}>
          <TouchableOpacity
            style={estilos.botaoVoltar}
            onPress={() => navigation.replace('Login')}
          >
            <Text style={estilos.textoBotaoVoltar}>Voltar</Text>
          </TouchableOpacity>
        </View>

        <Toast />
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const estilos = StyleSheet.create({
  container: {
    flexGrow: 1,
    justifyContent: 'center',
    padding: 20,
    backgroundColor: '#fff',
  },
  input: {
    borderWidth: 1,
    borderColor: '#ccc',
    marginBottom: 15,
    padding: 12,
    borderRadius: 6,
    fontSize: 16,
    width: '100%',
    backgroundColor: '#f9f9f9',
  },
  botao: {
    backgroundColor: '#4CAF50',
    padding: 14,
    borderRadius: 6,
    alignItems: 'center',
    width: '100%',
  },
  textoBotao: {
    color: '#fff',
    fontWeight: 'bold',
    fontSize: 16,
  },
  botaoVoltar: {
    backgroundColor: '#2196F3',
    paddingVertical: 6,
    paddingHorizontal: 16,
    borderRadius: 8,
    alignSelf: 'center',
  },
  textoBotaoVoltar: {
    color: '#fff',
    fontWeight: 'bold',
    fontSize: 16,
  },
});