import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  FlatList,
  TextInput,
  TouchableOpacity,
  Alert,
  ActivityIndicator,
  ImageBackground,
  Linking,
  ScrollView,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
  addDoc,
  updateDoc,
} from 'firebase/firestore';
import { firestore, auth } from '../services/firebaseConfig';

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  // Adicione outros UIDs aqui
];

interface Ensaio {
  id?: string;
  data: string;
  horario: string;
  observacoes: string;
  criadoEm: any;
}

interface Devocional {
  id?: string;
  link: string;
  mensagem?: string;
  criadoEm: any;
}

export default function EnsaiosScreen() {
  const navigation = useNavigation();
  const [ensaios, setEnsaios] = useState<Ensaio[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [novaData, setNovaData] = useState('');
  const [novoHorario, setNovoHorario] = useState('');
  const [novasObs, setNovasObs] = useState('');
  const [editandoId, setEditandoId] = useState<string | null>(null);
  const [editData, setEditData] = useState('');
  const [editHorario, setEditHorario] = useState('');
  const [editObs, setEditObs] = useState('');
  const [devocional, setDevocional] = useState<Devocional | null>(null);
  const [novoLink, setNovoLink] = useState('');
  const [novaMensagem, setNovaMensagem] = useState('');
  const [editMensagem, setEditMensagem] = useState('');
  const [editandoDevocional, setEditandoDevocional] = useState(false);
  const [criandoEnsaio, setCriandoEnsaio] = useState(false);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const ensaiosQuery = query(
      collection(firestore, 'ensaios'),
      orderBy('criadoEm', 'desc')
    );
    const devocionalQuery = query(
      collection(firestore, 'devocional'),
      orderBy('criadoEm', 'desc')
    );

    const unsubEnsaios = onSnapshot(ensaiosQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
      }));
      setEnsaios(data as Ensaio[]);
      setLoading(false);
    });

    const unsubDevocional = onSnapshot(devocionalQuery, (querySnapshot) => {
      const docs = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
      }));
      setDevocional(docs[0] || null);
    });

    return () => {
      unsubEnsaios();
      unsubDevocional();
    };
  }, []);

  const podeEditar = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  const excluirEnsaio = async (id: string) => {
    if (!podeEditar) return;
    try {
      await auth.currentUser?.getIdToken(true);
      await deleteDoc(doc(firestore, 'ensaios', id));
      setEnsaios(prev => prev.filter(e => e.id !== id));
    } catch (error: any) {
      console.log('Erro ao excluir ensaio:', error);
    }
  };

  const handleExcluirDevocional = async () => {
    if (!devocional?.id) return;
    try {
      await deleteDoc(doc(firestore, 'devocional', devocional.id));
      setDevocional(null);
      setEditandoDevocional(false);
      setNovoLink('');
      setNovaMensagem('');
      setEditMensagem('');
    } catch {
      Alert.alert('Erro', 'Não foi possível excluir o devocional.');
    }
  };

  const handleCriarEnsaio = async () => {
    if (!novaData.trim() || !novoHorario.trim()) {
      Alert.alert('Atenção', 'Preencha a data e o horário.');
      return;
    }
    try {
      await addDoc(collection(firestore, 'ensaios'), {
        data: novaData,
        horario: novoHorario,
        observacoes: novasObs,
        criadoEm: new Date(),
      });
      setNovaData('');
      setNovoHorario('');
      setNovasObs('');
      setCriandoEnsaio(false);
    } catch {
      Alert.alert('Erro', 'Não foi possível criar o ensaio.');
    }
  };

  const handleEditarEnsaio = (ensaio: Ensaio) => {
    setEditandoId(ensaio.id!);
    setEditData(ensaio.data);
    setEditHorario(ensaio.horario);
    setEditObs(ensaio.observacoes);
  };

  const handleSalvarEdicao = async () => {
    if (!editData.trim() || !editHorario.trim() || !editandoId) {
      Alert.alert('Atenção', 'Preencha a data e o horário.');
      return;
    }
    try {
      await updateDoc(doc(firestore, 'ensaios', editandoId), {
        data: editData,
        horario: editHorario,
        observacoes: editObs,
      });
      setEditandoId(null);
      setEditData('');
      setEditHorario('');
      setEditObs('');
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar o ensaio.');
    }
  };

  const handleSalvarDevocional = async () => {
    if (!novoLink.trim() && !novaMensagem.trim() && !editMensagem.trim()) {
      Alert.alert('Atenção', 'Informe o link ou a mensagem do devocional.');
      return;
    }
    try {
      if (devocional && devocional.id) {
        await updateDoc(doc(firestore, 'devocional', devocional.id), {
          link: novoLink,
          mensagem: editMensagem,
        });
      } else {
        await addDoc(collection(firestore, 'devocional'), {
          link: novoLink,
          mensagem: novaMensagem,
          criadoEm: new Date(),
        });
      }
      setEditandoDevocional(false);
      setNovoLink('');
      setNovaMensagem('');
      setEditMensagem('');
    } catch {
      Alert.alert('Erro', 'Não foi possível salvar o devocional.');
    }
  };

  const renderItem = ({ item }: { item: Ensaio }) => (
    <View style={styles.avisoBox}>
      {editandoId === item.id && podeEditar ? (
        <>
          <TextInput
            style={styles.input}
            value={editData}
            onChangeText={setEditData}
            placeholder="Data (ex: 10/06/2025)"
            placeholderTextColor="#aaa"
          />
          <TextInput
            style={styles.input}
            value={editHorario}
            onChangeText={setEditHorario}
            placeholder="Horário (ex: 19:30)"
            placeholderTextColor="#aaa"
          />
          <TextInput
            style={[styles.input, { minHeight: 40 }]}
            value={editObs}
            onChangeText={setEditObs}
            placeholder="Observações"
            placeholderTextColor="#aaa"
            multiline
          />
          <View style={styles.row}>
            <TouchableOpacity style={[styles.botao, styles.botaoSalvar]} onPress={handleSalvarEdicao}>
              <Text style={styles.botaoTexto}>Salvar</Text>
            </TouchableOpacity>
            <TouchableOpacity style={[styles.botao, styles.botaoCancelar]} onPress={() => setEditandoId(null)}>
              <Text style={styles.botaoTexto}>Cancelar</Text>
            </TouchableOpacity>
          </View>
        </>
      ) : (
        <>
          <Text style={styles.avisoTitulo}>Data: {item.data}</Text>
          <Text style={styles.avisoMensagem}>Horário: {item.horario}</Text>
          {item.observacoes ? (
            <Text style={styles.avisoMensagem}>Obs: {item.observacoes}</Text>
          ) : null}
          <Text style={styles.avisoData}>
            {item.criadoEm?.toDate ? item.criadoEm.toDate().toLocaleString() : ''}
          </Text>
          {podeEditar && (
            <View style={styles.row}>
              <TouchableOpacity
                style={[styles.botao, styles.botaoEditar]}
                onPress={() => handleEditarEnsaio(item)}
              >
                <Text style={styles.botaoTexto}>Editar</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.botao, styles.botaoExcluir]}
                onPress={() => excluirEnsaio(item.id!)}
              >
                <Text style={styles.botaoTexto}>Excluir</Text>
              </TouchableOpacity>
            </View>
          )}
        </>
      )}
    </View>
  );

  return (
    <ImageBackground
      source={require('../assets/Ima.jpg')}
      style={styles.bg}
      resizeMode="cover"
    >
      <KeyboardAvoidingView
        style={{ flex: 1 }}
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
        keyboardVerticalOffset={80}
      >
        <ScrollView
          contentContainerStyle={{ flexGrow: 1, paddingBottom: 24 }}
          keyboardShouldPersistTaps="handled"
        >
          <View style={styles.container}>
            <View style={styles.navRow}>
              <TouchableOpacity style={styles.homeButton} onPress={() => navigation.navigate('Inicio')}>
                <Text style={styles.homeButtonText}>🏠</Text>
              </TouchableOpacity>
              <Text style={styles.title}>🎶 Ensaios</Text>
              <TouchableOpacity style={styles.backButton} onPress={() => navigation.goBack()}>
                <Text style={styles.backButtonText}>←</Text>
              </TouchableOpacity>
            </View>

            {podeEditar && !criandoEnsaio && (
              <TouchableOpacity
                style={[styles.botao, styles.botaoCriar]}
                onPress={() => setCriandoEnsaio(true)}
              >
                <Text style={styles.botaoTexto}>Criar Ensaio</Text>
              </TouchableOpacity>
            )}

            {podeEditar && criandoEnsaio && (
              <View style={styles.novoAvisoBox}>
                <TextInput
                  style={styles.input}
                  placeholder="Data (ex: 10/06/2025)"
                  value={novaData}
                  onChangeText={setNovaData}
                  placeholderTextColor="#aaa"
                />
                <TextInput
                  style={styles.input}
                  placeholder="Horário (ex: 19:30)"
                  value={novoHorario}
                  onChangeText={setNovoHorario}
                  placeholderTextColor="#aaa"
                />
                <TextInput
                  style={[styles.input, { minHeight: 40 }]}
                  placeholder="Observações"
                  value={novasObs}
                  onChangeText={setNovasObs}
                  placeholderTextColor="#aaa"
                  multiline
                />
                <View style={styles.row}>
                  <TouchableOpacity style={[styles.botao, styles.botaoSalvar]} onPress={handleCriarEnsaio}>
                    <Text style={styles.botaoTexto}>Salvar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={[styles.botao, styles.botaoCancelar]}
                    onPress={() => {
                      setCriandoEnsaio(false);
                      setNovaData('');
                      setNovoHorario('');
                      setNovasObs('');
                    }}
                  >
                    <Text style={styles.botaoTexto}>Cancelar</Text>
                  </TouchableOpacity>
                </View>
              </View>
            )}

            {loading ? (
              <ActivityIndicator size="large" color="#2196F3" style={{ marginTop: 30 }} />
            ) : (
              <FlatList
                data={ensaios}
                keyExtractor={item => item.id!}
                renderItem={renderItem}
                ListEmptyComponent={
                  <Text style={{ color: '#888', marginTop: 30, textAlign: 'center' }}>Nenhum ensaio cadastrado.</Text>
                }
                scrollEnabled={false}
                contentContainerStyle={{ paddingBottom: 10 }}
              />
            )}

            <Text style={styles.title}>🙌🏼 Devocional</Text>
            {devocional && !editandoDevocional ? (
              <View style={styles.novoAvisoBox}>
                {devocional.link ? (
                  /^https?:\/\/|^www\./i.test(devocional.link.trim()) ? (
                    <TouchableOpacity
                      onPress={() => {
                        let url = devocional.link.trim();
                        if (!/^https?:\/\//i.test(url)) {
                          url = 'https://' + url;
                        }
                        Linking.openURL(url);
                      }}
                    >
                      <Text style={{ color: '#2196F3', textDecorationLine: 'underline', marginBottom: 6 }}>
                        {devocional.link}
                      </Text>
                    </TouchableOpacity>
                  ) : (
                    <Text style={{ color: '#444', marginBottom: 6 }}>{devocional.link}</Text>
                  )
                ) : null}
                {devocional.mensagem ? (
                  <Text style={{ marginTop: 2, color: '#444' }}>{devocional.mensagem}</Text>
                ) : null}
                {podeEditar && (
                  <View style={styles.row}>
                    <TouchableOpacity
                      style={[styles.botao, styles.botaoEditar]}
                      onPress={() => {
                        setEditandoDevocional(true);
                        setNovoLink(devocional.link || '');
                        setEditMensagem(devocional.mensagem || '');
                      }}
                    >
                      <Text style={styles.botaoTexto}>Editar</Text>
                    </TouchableOpacity>
                    <TouchableOpacity
                      style={[styles.botao, styles.botaoExcluir]}
                      onPress={handleExcluirDevocional}
                    >
                      <Text style={styles.botaoTexto}>Excluir</Text>
                    </TouchableOpacity>
                  </View>
                )}
              </View>
            ) : podeEditar && (
              <View style={styles.novoAvisoBox}>
                <TextInput
                  style={styles.input}
                  placeholder="Link do devocional (opcional)"
                  value={novoLink}
                  onChangeText={setNovoLink}
                  autoCapitalize="none"
                  autoCorrect={false}
                  placeholderTextColor="#aaa"
                />
                <TextInput
                  style={[styles.input, { minHeight: 40 }]}
                  placeholder="Mensagem do devocional (opcional)"
                  value={devocional ? editMensagem : novaMensagem}
                  onChangeText={devocional ? setEditMensagem : setNovaMensagem}
                  multiline
                  placeholderTextColor="#aaa"
                />
                <TouchableOpacity style={[styles.botao, styles.botaoCriar]} onPress={handleSalvarDevocional}>
                  <Text style={styles.botaoTexto}>Salvar Devocional</Text>
                </TouchableOpacity>
                {devocional && (
                  <TouchableOpacity
                    style={[styles.botao, styles.botaoCancelar, { marginTop: 4 }]}
                    onPress={() => setEditandoDevocional(false)}
                  >
                    <Text style={styles.botaoTexto}>Cancelar</Text>
                  </TouchableOpacity>
                )}
              </View>
            )}
          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </ImageBackground>
  );
}

const styles = StyleSheet.create({
  bg: {
    flex: 1,
    width: '100%',
    height: '100%',
  },
  container: {
    flex: 1,
    padding: 16,
    backgroundColor: 'transparent',
  },
  navRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    marginBottom: 14,
    marginTop: 10,
    backgroundColor: 'rgba(33,150,243,0.10)',
    borderRadius: 12,
    paddingVertical: 8,
    paddingHorizontal: 10,
    elevation: 2,
  },
  homeButton: {
    backgroundColor: '#2196F3',
    borderRadius: 8,
    padding: 8,
    minWidth: 36,
    alignItems: 'center',
    justifyContent: 'center',
  },
  homeButtonText: {
    color: '#fff',
    fontSize: 18,
    fontWeight: 'bold',
  },
  backButton: {
    backgroundColor: '#2196F3',
    borderRadius: 8,
    padding: 8,
    minWidth: 36,
    alignItems: 'center',
    justifyContent: 'center',
  },
  backButtonText: {
    color: '#fff',
    fontSize: 18,
    fontWeight: 'bold',
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 16,
    textAlign: 'center',
    color: '#1565c0',
    letterSpacing: 1,
    textShadowColor: '#e3f2fd',
    textShadowOffset: { width: 0, height: 1 },
    textShadowRadius: 2,
  },
  novoAvisoBox: {
    backgroundColor: '#fff',
    borderRadius: 14,
    padding: 16,
    marginBottom: 20,
    elevation: 4,
    shadowColor: '#2196F3',
    shadowOpacity: 0.10,
    shadowRadius: 10,
  },
  input: {
    borderWidth: 1,
    borderColor: '#90caf9',
    borderRadius: 10,
    padding: 12,
    fontSize: 16,
    backgroundColor: '#f5faff',
    color: '#222',
    marginBottom: 10,
  },
  botao: {
    backgroundColor: '#2196F3',
    paddingVertical: 8,
    paddingHorizontal: 18,
    borderRadius: 8,
    alignItems: 'center',
    justifyContent: 'center',
    marginTop: 6,
    alignSelf: 'center',
    minWidth: 120,
    elevation: 2,
    shadowColor: '#2196F3',
    shadowOpacity: 0.10,
    shadowRadius: 6,
  },
  botaoCriar: {
    backgroundColor: '#2196F3',
  },
  botaoSalvar: {
    backgroundColor: '#4CAF50',
    flex: 1,
    marginRight: 4,
  },
  botaoCancelar: {
    backgroundColor: '#aaa',
    flex: 1,
    marginLeft: 4,
  },
  botaoEditar: {
    backgroundColor: '#2196F3',
    flex: 1,
    marginRight: 4,
  },
  botaoExcluir: {
    backgroundColor: '#F44336',
    flex: 1,
    marginLeft: 4,
  },
  botaoTexto: {
    color: '#fff',
    fontWeight: 'bold',
    fontSize: 16,
    letterSpacing: 0.5,
  },
  avisoBox: {
    backgroundColor: '#fff',
    borderRadius: 14,
    padding: 16,
    marginBottom: 16,
    elevation: 2,
    shadowColor: '#2196F3',
    shadowOpacity: 0.08,
    shadowRadius: 8,
    borderLeftWidth: 5,
    borderLeftColor: '#2196F3',
  },
  avisoTitulo: {
    fontWeight: 'bold',
    fontSize: 18,
    marginBottom: 4,
    color: '#2196F3',
    letterSpacing: 0.5,
  },
  avisoMensagem: {
    fontSize: 15,
    color: '#444',
    marginBottom: 6,
  },
  avisoData: {
    fontSize: 12,
    color: '#888',
    marginBottom: 2,
    textAlign: 'right',
  },
  row: {
    flexDirection: 'row',
    marginTop: 8,
    justifyContent: 'space-between',
  },
});