import React, { useEffect, useState } from 'react';
import { View, ActivityIndicator, StyleSheet } from 'react-native';
import { NavigationContainer } from '@react-navigation/native';
import { onAuthStateChanged, User } from 'firebase/auth';

import AuthNavigator from './src/navigation/AuthNavigator';
import AppNavigator from './src/navigation/AppNavigator';
import { auth } from './src/services/firebaseConfig';
import Toast from 'react-native-toast-message';

export default function App(): JSX.Element {
  const [usuario, setUsuario] = useState<User | null>(null);
  const [carregando, setCarregando] = useState(true);

  // Observa mudanças no estado de autenticação
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (usuarioAtual: User | null) => {
      // Só considera logado se o email estiver verificado
      if (usuarioAtual && usuarioAtual.emailVerified) {
        setUsuario(usuarioAtual);
      } else {
        setUsuario(null);
      }
      setCarregando(false);
    });

    return unsubscribe; // limpa o observer ao desmontar
  }, []);

  // Mostra indicador de carregamento enquanto verifica login
  if (carregando) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#007AFF" />
      </View>
    );
  }

  return (
    <NavigationContainer>
      {/* Alterna entre as rotas com base no login */}
      {usuario ? <AppNavigator /> : <AuthNavigator />}
      <Toast />
    </NavigationContainer>
  );
}

const styles = StyleSheet.create({
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#fff',
  },
});
