import React, { useEffect, useState } from 'react';
import { View, Text, StyleSheet, ActivityIndicator, ScrollView, TouchableOpacity, TextInput, Alert, ImageBackground } from 'react-native';
import { getFirestore, doc, getDoc, updateDoc, deleteDoc } from 'firebase/firestore';
import { RouteProp, useRoute, useNavigation } from '@react-navigation/native';
import { auth } from '../services/firebaseConfig';
import type { ListaRotasPrincipais } from '../types';

type RotaDetalhesEscala = RouteProp<ListaRotasPrincipais, 'DetalhesEscala'>;

const db = getFirestore();

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'bVpx7GAuLuTbRVWfPOT57vgO9cL2',
  // Adicione outros UIDs aqui
];

// Mapeamento de emojis para cada campo
const iconesPorCampo: Record<string, string> = {
  data: '📅',
  responsavel: '🧑‍💼',
  violao: '🎸',
  teclado: '🎹',
  bateria: '🥁',
  guitarra: '🎸',
  contrabaixo: '🪕',
  vocal: '🎙️',
  backVocal1: '🎤',
  backVocal2: '🎤',
  backVocal3: '🎤',
  backVocal4: '🎤',
  som: '🔊',
  projecao: '🖥️',
  midia1: '📱',
  midia2: '📱',
  midia3: '🎥',
  midia4: '📸',
  criadoEm: '⏰',
};

function formatarData(valor: any) {
  if (valor?.toDate) {
    return valor.toDate().toLocaleString('pt-BR', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  }
  if (typeof valor === 'string' && !isNaN(Date.parse(valor))) {
    return new Date(valor).toLocaleString('pt-BR');
  }
  return String(valor);
}

const ordemCampos: string[] = [
  'data',
  'responsavel',
  'violao',
  'teclado',
  'bateria',
  'guitarra',
  'contrabaixo',
  'vocal',
  'backVocal1',
  'backVocal2',
  'backVocal3',
  'backVocal4',
  'som',
  'projecao',
  'midia1',
  'midia2',
  'midia3',
  'midia4',
  'criadoEm'
];

function labelComAcento(campo: string): string {
  switch (campo) {
    case 'data': return 'Data';
    case 'responsavel': return 'Responsável';
    case 'violao': return 'Violão';
    case 'teclado': return 'Teclado';
    case 'bateria': return 'Bateria';
    case 'guitarra': return 'Guitarra';
    case 'contrabaixo': return 'Contrabaixo';
    case 'vocal': return 'Vocal';
    case 'backVocal1': return 'Back Vocal 1';
    case 'backVocal2': return 'Back Vocal 2';
    case 'backVocal3': return 'Back Vocal 3';
    case 'backVocal4': return 'Back Vocal 4';
    case 'som': return 'Som';
    case 'projecao': return 'Projeção';
    case 'midia1': return 'Mídia 1';
    case 'midia2': return 'Mídia 2';
    case 'midia3': return 'Mídia 3';
    case 'midia4': return 'Mídia 4';
    case 'criadoEm': return 'Criado em';
    default: return campo.charAt(0).toUpperCase() + campo.slice(1);
  }
}

export default function TelaDetalhesEscala(): JSX.Element {
  const route = useRoute<RotaDetalhesEscala>();
  const navigation = useNavigation();
  const id = route.params?.id;

  const [escala, setEscala] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [editando, setEditando] = useState(false);
  const [escalaEdit, setEscalaEdit] = useState<any>({});

  useEffect(() => {
    setUidAtual(auth.currentUser?.uid ?? null);

    if (!id) return;
    const carregarEscala = async () => {
      try {
        const docSnap = await getDoc(doc(db, 'escalas', id));
        if (docSnap.exists()) {
          setEscala(docSnap.data());
          setEscalaEdit(docSnap.data());
        } else {
          setEscala(null);
        }
      } catch (e) {
        setEscala(null);
      } finally {
        setLoading(false);
      }
    };
    carregarEscala();
  }, [id]);

  // Máscara automática para data dd/mm/aaaa
  const handleChange = (campo: string, valor: string) => {
    if (campo === 'data') {
      let cleaned = valor.replace(/\D/g, '');
      if (cleaned.length > 8) cleaned = cleaned.slice(0, 8);
      let formatted = cleaned;
      if (cleaned.length > 4) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2, 4)}/${cleaned.slice(4)}`;
      } else if (cleaned.length > 2) {
        formatted = `${cleaned.slice(0, 2)}/${cleaned.slice(2)}`;
      }
      setEscalaEdit((prev: any) => ({ ...prev, [campo]: formatted }));
    } else {
      setEscalaEdit((prev: any) => ({ ...prev, [campo]: valor }));
    }
  };

  const salvarAlteracoes = async () => {
    if (!id) {
      Alert.alert('Erro', 'ID da escala não informado.');
      return;
    }
    try {
      await updateDoc(doc(db, 'escalas', id), escalaEdit);
      setEscala({ ...escalaEdit });
      setEditando(false);
      Alert.alert('Sucesso', 'Escala atualizada com sucesso!');
    } catch (error) {
      Alert.alert('Erro', 'Não foi possível salvar as alterações.');
    }
  };

  const confirmarExclusao = async () => {
    if (!id) {
      Alert.alert('Erro', 'ID da escala não informado.');
      return;
    }
    Alert.alert(
      'Excluir Escala',
      'Tem certeza que deseja excluir esta escala?',
      [
        { text: 'Cancelar', style: 'cancel' },
        {
          text: 'Excluir',
          style: 'destructive',
          onPress: async () => {
            try {
              await deleteDoc(doc(db, 'escalas', id));
              Alert.alert('Sucesso', 'Escala excluída com sucesso!');
              // @ts-ignore
              if (navigation && navigation.goBack) navigation.goBack();
            } catch (error) {
              Alert.alert('Erro', 'Não foi possível excluir a escala.');
            }
          },
        },
      ],
      { cancelable: true }
    );
  };

  if (!id) {
    return (
      <ImageBackground
        source={require('../assets/fun.jpg')}
        style={styles.bg}
        resizeMode="cover"
      >
        <View style={styles.loadingContainer}>
          <Text>ID da escala não informado.</Text>
        </View>
      </ImageBackground>
    );
  }

  if (loading) {
    return (
      <ImageBackground
        source={require('../assets/fun.jpg')}
        style={styles.bg}
        resizeMode="cover"
      >
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#2196F3" />
        </View>
      </ImageBackground>
    );
  }

  if (!escala) {
    return (
      <ImageBackground
        source={require('../assets/fun.jpg')}
        style={styles.bg}
        resizeMode="cover"
      >
        <View style={styles.loadingContainer}>
          <Text>Escala não encontrada.</Text>
        </View>
      </ImageBackground>
    );
  }

  const camposOrdenados = [
    ...ordemCampos.filter((campo) => escala[campo] !== undefined),
    ...Object.keys(escala).filter((campo) => !ordemCampos.includes(campo)),
  ];

  const permitido = !!uidAtual && UIDS_PERMITIDOS.includes(uidAtual);

  return (
    <ImageBackground
      source={require('../assets/fun.jpg')}
      style={styles.bg}
      resizeMode="cover"
    >
      <ScrollView contentContainerStyle={styles.container}>
        <View style={styles.navRow}>
          <TouchableOpacity style={styles.homeButton} onPress={() => navigation.navigate('Inicio')}>
            <Text style={styles.homeButtonText}>🏠</Text>
          </TouchableOpacity>
          <Text style={styles.titulo}>Detalhes da Escala</Text>
          <TouchableOpacity style={styles.backButton} onPress={() => navigation.goBack()}>
            <Text style={styles.backButtonText}>←</Text>
          </TouchableOpacity>
        </View>
        <View style={styles.card}>
          {camposOrdenados.map((campo) => (
            <View key={campo} style={styles.itemAltoRelevo}>
              <View style={styles.labelValueRow}>
                <View style={styles.labelBox}>
                  <Text style={styles.emoji}>{iconesPorCampo[campo] || ''}</Text>
                  <Text style={styles.campo}>{labelComAcento(campo)}</Text>
                </View>
                <View style={styles.valorBox}>
                  {editando && campo !== 'criadoEm' ? (
                    <TextInput
                      style={[styles.valor, styles.inputEdit]}
                      value={escalaEdit[campo]}
                      onChangeText={text => handleChange(campo, text)}
                      placeholder={labelComAcento(campo)}
                      placeholderTextColor="#90caf9"
                      maxLength={campo === 'data' ? 10 : 60}
                      selectionColor="#1976d2"
                      keyboardType={campo === 'data' ? 'numeric' : 'default'}
                      textAlign="right"
                      underlineColorAndroid="transparent"
                    />
                  ) : (
                    <Text style={styles.valor}>
                      {campo === 'criadoEm' || campo === 'criadoem'
                        ? formatarData(escala[campo])
                        : String(escala[campo])}
                    </Text>
                  )}
                </View>
              </View>
            </View>
          ))}

          {permitido && (
            <View style={styles.acoesAdmin}>
              {!editando ? (
                <>
                  <TouchableOpacity
                    style={styles.botaoEditar}
                    onPress={() => setEditando(true)}
                  >
                    <Text style={styles.textoBotao}>Editar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={styles.botaoExcluir}
                    onPress={confirmarExclusao}
                  >
                    <Text style={styles.textoBotao}>Excluir</Text>
                  </TouchableOpacity>
                </>
              ) : (
                <>
                  <TouchableOpacity
                    style={styles.botaoSalvar}
                    onPress={salvarAlteracoes}
                  >
                    <Text style={styles.textoBotao}>Salvar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={styles.botaoCancelar}
                    onPress={() => {
                      setEditando(false);
                      setEscalaEdit({ ...escala });
                    }}
                  >
                    <Text style={styles.textoBotao}>Cancelar</Text>
                  </TouchableOpacity>
                </>
              )}
            </View>
          )}
        </View>
      </ScrollView>
    </ImageBackground>
  );
}

