import React, { useEffect, useState } from 'react';
import {
  View,
  Text,
  FlatList,
  TouchableOpacity,
  StyleSheet,
  ActivityIndicator,
  ImageBackground,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import {
  collection,
  onSnapshot,
  query,
  orderBy,
  deleteDoc,
  doc,
} from 'firebase/firestore';
import { firestore, auth } from '../services/firebaseConfig';
import type { ListaRotasPrincipais } from '../types';
import type { NativeStackNavigationProp } from '@react-navigation/native-stack';

type NavigationProp = NativeStackNavigationProp<ListaRotasPrincipais, 'Repertorios'>;

const UIDS_PERMITIDOS = [
  'qAvyxYtraUPmd06d3jufwqPi7vo2',
  'g8KmZsmMqfPEqAM3NWF7qs33Gid2',
  'DibIuShhIqbApUpHAIKSG8w2dE02',
  // Adicione outros UIDs aqui
];

export default function RepertoiresScreen(): JSX.Element {
  const navigation = useNavigation<NavigationProp>();
  const [repertorios, setRepertorios] = useState<any[]>([]);
  const [uidAtual, setUidAtual] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const uid = auth.currentUser?.uid ?? null;
    setUidAtual(uid);

    const repertoriosQuery = query(
      collection(firestore, 'repertorios'),
      orderBy('criadoEm', 'desc')
    );

    const unsubscribe = onSnapshot(repertoriosQuery, (querySnapshot) => {
      const data = querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data(),
      }));
      setRepertorios(data);
      setLoading(false);
    }, (error) => {
      console.log('Erro ao buscar repertórios:', error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const excluirRepertorio = async (id: string) => {
    if (!uidAtual || !UIDS_PERMITIDOS.includes(uidAtual)) return;
    try {
      await auth.currentUser?.getIdToken(true);
      await deleteDoc(doc(firestore, 'repertorios', id));
      setRepertorios(prev => prev.filter(rep => rep.id !== id));
    } catch (error: any) {
      console.log('Erro ao excluir repertório:', error);
    }
  };

  const renderItem = ({ item }: { item: any }) => (
    <View style={styles.item}>
      <TouchableOpacity
        onPress={() => navigation.navigate('DetalheRepertorio', { repertorio: item })}
        style={{ flex: 1 }}
      >
        <Text style={styles.itemTitle}>{item.titulo || 'Sem título'}</Text>
        <View style={styles.itemInfoRow}>
          <View style={styles.infoBadge}>
            <Text style={styles.infoBadgeText}>Data</Text>
            <Text style={styles.infoBadgeValue}>{item.data || '-'}</Text>
          </View>
          <View style={styles.infoBadge}>
            <Text style={styles.infoBadgeText}>Responsável</Text>
            <Text style={styles.infoBadgeValue}>{item.responsavel || '-'}</Text>
          </View>
          <View style={styles.infoBadge}>
            <Text style={styles.infoBadgeText}>Músicas</Text>
            <Text style={styles.infoBadgeValue}>{item.musicas ? item.musicas.length : 0}</Text>
          </View>
        </View>
      </TouchableOpacity>
      {uidAtual && UIDS_PERMITIDOS.includes(uidAtual) && (
        <TouchableOpacity
          style={styles.botaoExcluir}
          onPress={() => excluirRepertorio(item.id)}
        >
          <Text style={styles.textoBotao}>🗑️</Text>
        </TouchableOpacity>
      )}
    </View>
  );

  return (
    <ImageBackground
      source={require('../assets/image.jpg')}
      style={styles.bg}
      resizeMode="cover"
    >
      <View style={styles.container}>
        <View style={styles.navRow}>
          <TouchableOpacity style={styles.homeButton} onPress={() => navigation.navigate('Inicio')}>
            <Text style={styles.homeButtonText}>🏠</Text>
          </TouchableOpacity>
          <Text style={styles.title}>🎼 Repertórios</Text>
          <TouchableOpacity style={styles.backButton} onPress={() => navigation.goBack()}>
            <Text style={styles.backButtonText}>←</Text>
          </TouchableOpacity>
        </View>
        {uidAtual && UIDS_PERMITIDOS.includes(uidAtual) && (
          <TouchableOpacity
            style={styles.addButton}
            onPress={() => navigation.navigate('AdicionarRepertorio')}
          >
            <Text style={styles.addButtonText}>➕Novo Repertório</Text>
          </TouchableOpacity>
        )}
        {loading ? (
          <ActivityIndicator size="large" color="#2196F3" style={{ marginTop: 40 }} />
        ) : (
          <FlatList
            data={repertorios}
            keyExtractor={item => item.id}
            renderItem={renderItem}
            contentContainerStyle={styles.list}
            ListEmptyComponent={<Text style={styles.emptyText}>Nenhum repertório encontrado.</Text>}
          />
        )}
      </View>
    </ImageBackground>
  );
}

