import React, { useState } from 'react';
import {
  TextInput,
  TouchableOpacity,
  Text,
  Alert,
  ActivityIndicator,
  StyleSheet,
  KeyboardAvoidingView,
  Platform,
  ScrollView,
} from 'react-native';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../services/firebaseConfig';
import { getFirestore, doc, getDoc } from 'firebase/firestore';

const db = getFirestore();

export default function TelaLogin({ navigation }: any): JSX.Element {
  const [email, setEmail] = useState('');
  const [senha, setSenha] = useState('');
  const [carregando, setCarregando] = useState(false);

  const fazerLogin = async () => {
    if (!email || !senha) {
      Alert.alert('Erro', 'Preencha email e senha!');
      return;
    }

    setCarregando(true);

    try {
      const credenciais = await signInWithEmailAndPassword(auth, email, senha);
      const usuario = credenciais.user;

      if (!usuario.emailVerified) {
        Alert.alert(
          'Email não verificado',
          'Por favor, confirme seu email antes de fazer login.'
        );
        await auth.signOut();
        setCarregando(false);
        return;
      }

      // Verifica se o usuário existe no Firestore (ID = uid)
      const usuarioRef = doc(db, 'usuarios', usuario.uid);
      const usuarioSnap = await getDoc(usuarioRef);

      if (!usuarioSnap.exists()) {
        Alert.alert(
          'Usuário não cadastrado',
          'Seu usuário não foi encontrado no banco de dados. Faça o cadastro primeiro.'
        );
        await auth.signOut();
        setCarregando(false);
        return;
      }

      // O App.tsx faz o redirecionamento automático para a tela de início

    } catch (erro: any) {
      let mensagem = 'Erro ao fazer login. Tente novamente.';

      if (erro.code) {
        switch (erro.code) {
          case 'auth/user-not-found':
            mensagem = 'Usuário não encontrado.';
            break;
          case 'auth/wrong-password':
            mensagem = 'Senha incorreta.';
            break;
          case 'auth/invalid-email':
            mensagem = 'Email inválido.';
            break;
          default:
            mensagem = erro.message || mensagem;
        }
      }

      Alert.alert('Erro', mensagem);
    } finally {
      setCarregando(false);
    }
  };

  return (
    <KeyboardAvoidingView
      style={{ flex: 1 }}
      behavior={Platform.OS === 'ios' ? 'padding' : undefined}
    >
      <ScrollView
        contentContainerStyle={estilos.container}
        keyboardShouldPersistTaps="handled"
      >
        <Text style={estilos.titulo}>Login</Text>

        <TextInput
          placeholder="Email"
          value={email}
          onChangeText={setEmail}
          keyboardType="email-address"
          autoCapitalize="none"
          style={estilos.entrada}
          editable={!carregando}
        />

        <TextInput
          placeholder="Senha"
          value={senha}
          onChangeText={setSenha}
          secureTextEntry
          style={estilos.entrada}
          editable={!carregando}
        />

        {carregando ? (
          <ActivityIndicator
            size="large"
            color="#4CAF50"
            style={{ marginVertical: 10 }}
          />
        ) : (
          <TouchableOpacity style={estilos.botao} onPress={fazerLogin}>
            <Text style={estilos.textoBotao}>Entrar</Text>
          </TouchableOpacity>
        )}

        <TouchableOpacity
          onPress={() => navigation.navigate('Cadastro')}
          disabled={carregando}
        >
          <Text style={estilos.textoCadastro}>
            Não tem conta? Cadastre-se
          </Text>
        </TouchableOpacity>
      </ScrollView>
    </KeyboardAvoidingView>
  );
}

const estilos = StyleSheet.create({
  container: {
    flexGrow: 1,
    justifyContent: 'center',
    padding: 20,
    backgroundColor: '#fff',
  },
  titulo: {
    fontSize: 28,
    fontWeight: 'bold',
    marginBottom: 30,
    textAlign: 'center',
  },
  entrada: {
    borderWidth: 1,
    borderColor: '#aaa',
    borderRadius: 6,
    padding: 12,
    marginBottom: 15,
    fontSize: 16,
    width: '100%',
    backgroundColor: '#f9f9f9',
  },
  botao: {
    backgroundColor: '#2196F3',
    paddingVertical: 14,
    borderRadius: 6,
    alignItems: 'center',
    marginTop: 10,
    width: '100%',
  },
  textoBotao: {
    color: '#fff',
    fontWeight: 'bold',
    fontSize: 18,
    letterSpacing: 1,
  },
  textoCadastro: {
    marginTop: 25,
    color: '#1E90FF',
    textAlign: 'center',
    textDecorationLine: 'underline',
    fontSize: 15,
  },
});
