import React, { useEffect, useState } from 'react';
import { View, Text, StyleSheet, FlatList, TouchableOpacity, TextInput, ImageBackground, Alert, Modal, ScrollView } from 'react-native';
import { getFirestore, collection, getDocs, addDoc, Timestamp, updateDoc, doc, arrayUnion } from 'firebase/firestore';
import { MaterialIcons, MaterialCommunityIcons } from '@expo/vector-icons';
import { useNavigation } from '@react-navigation/native';

const db = getFirestore();

type Aniversariante = {
  id?: string;
  nome: string;
  data: string; // formato: 'dd-mm-aaaa'
  mensagens?: string[];
};

// Função para formatar data com barra automaticamente
function formatarDataInput(text: string) {
  let cleaned = text.replace(/\D/g, '');
  let formatted = '';
  if (cleaned.length > 4) {
    formatted = cleaned.replace(/^(\d{2})(\d{2})(\d{0,4}).*/, '$1/$2/$3');
  } else if (cleaned.length > 2) {
    formatted = cleaned.replace(/^(\d{2})(\d{0,2})/, '$1/$2');
  } else {
    formatted = cleaned;
  }
  return formatted;
}

export default function TelaAniversariantes() {
  const [aniversariantes, setAniversariantes] = useState<Aniversariante[]>([]);
  const [novoNome, setNovoNome] = useState('');
  const [novaData, setNovaData] = useState('');
  const [modalVisible, setModalVisible] = useState(false);
  const [mensagem, setMensagem] = useState('');
  const [aniversarianteSelecionado, setAniversarianteSelecionado] = useState<Aniversariante | null>(null);
  const [felicitacaoHoje, setFelicitacaoHoje] = useState<Aniversariante[]>([]);
  const [todosAniversariantes, setTodosAniversariantes] = useState<Aniversariante[]>([]);
  const [mostrarForm, setMostrarForm] = useState(false);

  const navigation = useNavigation();

  useEffect(() => {
    buscarAniversariantes();
  }, []);

  async function buscarAniversariantes() {
    try {
      const snap = await getDocs(collection(db, 'aniversariantes'));
      const lista: Aniversariante[] = [];
      snap.forEach(docSnap => {
        const data = docSnap.data();
        lista.push({ id: docSnap.id, ...data, mensagens: data.mensagens || [] } as Aniversariante);
      });

      // Todos os aniversariantes (ordenados por mês e dia)
      const todos = [...lista].sort((a, b) => {
        const [diaA, mesA] = a.data.split('-').map(Number);
        const [diaB, mesB] = b.data.split('-').map(Number);
        if (mesA !== mesB) return mesA - mesB;
        return diaA - diaB;
      });
      setTodosAniversariantes(todos);

      // Filtrar por mês atual
      const mesAtual = new Date().getMonth() + 1;
      const filtrados = lista.filter(a => {
        const [dia, mes] = a.data.split('-');
        return Number(mes) === mesAtual;
      });
      setAniversariantes(filtrados);

      // Filtrar aniversariantes de hoje
      const hoje = new Date();
      const diaHoje = String(hoje.getDate()).padStart(2, '0');
      const mesHoje = String(hoje.getMonth() + 1).padStart(2, '0');
      const aniversariantesHoje = lista.filter(a => {
        const [dia, mes] = a.data.split('-');
        return dia === diaHoje && mes === mesHoje;
      });
      setFelicitacaoHoje(aniversariantesHoje);

    } catch (e) {
      Alert.alert('Erro', 'Não foi possível carregar os aniversariantes.');
    }
  }

  async function adicionarAniversariante() {
    const dataFormatada = novaData.replace(/\//g, '-');
    if (!novoNome || !dataFormatada.match(/^\d{2}-\d{2}-\d{4}$/)) {
      Alert.alert('Preencha corretamente o nome e a data (dd-mm-aaaa)');
      return;
    }
    try {
      await addDoc(collection(db, 'aniversariantes'), {
        nome: novoNome,
        data: dataFormatada,
        criadoEm: Timestamp.now(),
        mensagens: [],
      });
      setNovoNome('');
      setNovaData('');
      setMostrarForm(false);
      buscarAniversariantes();
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível adicionar.');
    }
  }

  async function enviarMensagem() {
    if (!mensagem || !aniversarianteSelecionado) return;
    try {
      const ref = doc(db, 'aniversariantes', aniversarianteSelecionado.id!);
      await updateDoc(ref, {
        mensagens: arrayUnion(mensagem),
      });
      setMensagem('');
      setModalVisible(false);
      buscarAniversariantes();
      Alert.alert('Mensagem enviada!', `Sua mensagem para ${aniversarianteSelecionado.nome} foi enviada.`);
    } catch (e) {
      Alert.alert('Erro', 'Não foi possível enviar a mensagem.');
    }
  }

  return (
    <ImageBackground
      source={require('../assets/fun.jpg')}
      style={estilos.bg}
      resizeMode="cover"
    >
      <ScrollView contentContainerStyle={estilos.scroll}>
        <View style={estilos.container}>
          {/* Botão Home à esquerda e Voltar à direita */}
          <View style={estilos.headerBotoes}>
            <TouchableOpacity
              style={estilos.headerBotao}
              onPress={() => navigation.navigate('Inicio' as never)}
            >
              <MaterialIcons name="home" size={28} color="#2196F3" />
            </TouchableOpacity>
            <View style={{ flex: 1 }} />
            <TouchableOpacity
              style={estilos.headerBotao}
              onPress={() => navigation.goBack()}
            >
              <MaterialIcons name="arrow-forward" size={28} color="#2196F3" />
            </TouchableOpacity>
          </View>

          <Text style={estilos.titulo}>🎂 Aniversariantes do Mês</Text>

          {/* Felicitação especial para aniversariantes do dia */}
          {felicitacaoHoje.length > 0 && (
            <View style={estilos.felicitacaoBox}>
              <Text style={estilos.felicitacaoTitulo}>🎉 Hoje é aniversário de:</Text>
              {felicitacaoHoje.map((a) => (
                <View key={a.id || a.nome + a.data} style={{ width: '100%' }}>
                  <Text style={estilos.felicitacaoNome}>
                    {a.nome} <Text style={{ fontSize: 18 }}>🎈</Text>
                  </Text>
                  {/* Mensagens de parabéns */}
                  {a.mensagens && a.mensagens.length > 0 && (
                    <View style={estilos.mensagensBox}>
                      {a.mensagens.map((msg, idx) => (
                        <Text key={idx} style={estilos.mensagemItem}>💬 {msg}</Text>
                      ))}
                    </View>
                  )}
                </View>
              ))}
              <Text style={estilos.felicitacaoMensagem}>
                Parabéns! Que Deus abençoe grandemente sua vida! 🙏
              </Text>
            </View>
          )}

          {/* Botão para mostrar/ocultar formulário */}
          {!mostrarForm && (
            <TouchableOpacity
              style={[estilos.botaoAddMelhorado, { marginBottom: 18 }]}
              onPress={() => setMostrarForm(true)}
            >
              <MaterialIcons name="add-circle" size={26} color="#fff" />
              <Text style={estilos.textoBotaoAdd}>Adicionar aniversariante</Text>
            </TouchableOpacity>
          )}

          {mostrarForm && (
            <View style={estilos.formMelhorada}>
              <View style={estilos.inputBox}>
                <MaterialIcons name="person" size={22} color="#2196F3" style={{ marginRight: 6 }} />
                <TextInput
                  style={estilos.inputMelhorado}
                  placeholder="Seu nome"
                  value={novoNome}
                  onChangeText={setNovoNome}
                  placeholderTextColor="#2196F3"
                  autoCapitalize="words"
                />
              </View>
              <View style={estilos.inputBox}>
                <MaterialIcons name="calendar-today" size={20} color="#2196F3" style={{ marginRight: 6 }} />
                <TextInput
                  style={estilos.inputMelhorado}
                  placeholder="Data (dd/mm/aaaa)"
                  value={novaData}
                  onChangeText={t => setNovaData(formatarDataInput(t))}
                  placeholderTextColor="#2196F3"
                  keyboardType="numeric"
                  maxLength={10}
                />
              </View>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', gap: 10 }}>
                <TouchableOpacity
                  style={[estilos.botaoAddMelhorado, { flex: 1, backgroundColor: '#e53935' }]}
                  onPress={() => setMostrarForm(false)}
                >
                  <MaterialIcons name="close" size={22} color="#fff" />
                  <Text style={estilos.textoBotaoAdd}>Cancelar</Text>
                </TouchableOpacity>
                <TouchableOpacity
                  style={[estilos.botaoAddMelhorado, { flex: 1 }]}
                  onPress={adicionarAniversariante}
                >
                  <MaterialIcons name="check-circle" size={22} color="#fff" />
                  <Text style={estilos.textoBotaoAdd}>Salvar</Text>
                </TouchableOpacity>
              </View>
            </View>
          )}

          <Text style={estilos.subtitulo}>🎈 Aniversariantes deste mês</Text>
          <FlatList
            data={aniversariantes}
            keyExtractor={item => item.id || item.nome + item.data}
            contentContainerStyle={{ paddingBottom: 10 }}
            renderItem={({ item }) => (
              <View style={estilos.card}>
                <MaterialIcons name="cake" size={28} color="#2196F3" style={{ marginRight: 10 }} />
                <View style={{ flex: 1 }}>
                  <Text style={estilos.nome}>{item.nome}</Text>
                  <Text style={estilos.data}>{item.data}</Text>
                </View>
                <TouchableOpacity
                  style={estilos.botaoParabens}
                  onPress={() => {
                    setAniversarianteSelecionado(item);
                    setModalVisible(true);
                  }}
                >
                  <MaterialCommunityIcons name="message-text" size={20} color="#fff" />
                  <Text style={estilos.textoParabens}>Parabéns</Text>
                </TouchableOpacity>
              </View>
            )}
            ListEmptyComponent={
              <Text style={{ color: '#2196F3', textAlign: 'center', marginTop: 10 }}>
                Nenhum aniversariante este mês.
              </Text>
            }
          />

          <Text style={estilos.subtitulo}>🎉 Todos os aniversariantes</Text>
          <FlatList
            data={todosAniversariantes}
            keyExtractor={item => item.id || item.nome + item.data}
            contentContainerStyle={{ paddingBottom: 40 }}
            renderItem={({ item }) => (
              <View style={estilos.cardAll}>
                <MaterialIcons name="cake" size={22} color="#43e97b" style={{ marginRight: 8 }} />
                <Text style={estilos.nomeAll}>{item.nome}</Text>
                <Text style={estilos.dataAll}>{item.data}</Text>
              </View>
            )}
            ListEmptyComponent={
              <Text style={{ color: '#2196F3', textAlign: 'center', marginTop: 10 }}>
                Nenhum aniversariante cadastrado.
              </Text>
            }
          />

          <Modal
            visible={modalVisible}
            animationType="slide"
            transparent
            onRequestClose={() => setModalVisible(false)}
          >
            <View style={estilos.modalBg}>
              <View style={estilos.modalBox}>
                <Text style={estilos.modalTitulo}>
                  Enviar mensagem para {aniversarianteSelecionado?.nome}
                </Text>
                <TextInput
                  style={estilos.inputModal}
                  placeholder="Digite sua mensagem"
                  value={mensagem}
                  onChangeText={setMensagem}
                  placeholderTextColor="#2196F3"
                  multiline
                />
                <View style={{ flexDirection: 'row', justifyContent: 'flex-end', gap: 12 }}>
                  <TouchableOpacity onPress={() => setModalVisible(false)}>
                    <Text style={{ color: '#e53935', fontWeight: 'bold', fontSize: 16 }}>Cancelar</Text>
                  </TouchableOpacity>
                  <TouchableOpacity onPress={enviarMensagem}>
                    <Text style={{ color: '#2196F3', fontWeight: 'bold', fontSize: 16 }}>Enviar</Text>
                  </TouchableOpacity>
                </View>
              </View>
            </View>
          </Modal>
        </View>
      </ScrollView>
    </ImageBackground>
  );
}

